-- Loot data registry. Data files (generated by ../scraper) call
-- ns.Data:Register(...) at load time.
--
-- Shape of one instance:
-- {
--     id = "DEADMINES",           -- stable key
--     name = "The Deadmines",
--     category = "DUNGEON",       -- DUNGEON | RAID | PVP | FACTION | COLLECTION | PROFESSION | CLASS
--     zone = "Westfall",
--     levelRange = { 17, 26 },    -- optional
--     encounters = {
--         { id = "RHAHKZOR", name = "Rhahk'Zor", loot = {
--             { itemID = 872, dropRate = 0.21 },  -- dropRate optional (0-1)
--         } },
--         -- optional: note = "Rare" (shown under the encounter name)
--         -- optional: display = <creature display ID> (its map pin portrait)
--         -- optional: level = <boss level, -1 for ??> (its loot header portrait)
--         -- Encounters whose NPCs each drop their own loot (the Ring of Law)
--         -- give every item boss = N, the Nth of its bosses in Bosses.lua; the
--         -- loot pane shows a folding section per boss.
--     },
-- }
--
-- PvP vendor lists add faction = "Alliance" | "Horde" (the UI shows one
-- side at a time) and give items a vendor price, cost = <copper>, in place
-- of a drop rate. Their encounters are honor ranks or reputation standings.
-- Faction lists work the same way, with zone naming where the faction's
-- quartermaster is; quest rewards there have no cost. An item bought with
-- another item (a reputation's tokens) has costItem = <that item's ID>,
-- costCount = <how many> in place of cost.
--
-- Collections (mounts, pets, tabards, item sets, world events) come from
-- AtlasLootClassic's Collections module; their zone is a kind ("Item sets",
-- "Holiday") and their encounters are sections or single item sets. A set
-- made for one class names it, classes = "Mage" (as class quests do), which
-- the Classes tab's Tier Sets section lists it by.
-- A list of what a currency buys (the Tarnished Undermine Real's vendor,
-- kept by hand in scraper/collections/currency_vendors.json) comes first and
-- adds currencyID = <the game's currency ID>: the list shows the currency's
-- icon and, on a client in another language, the game's name for it. Its
-- zone is where the vendor stands, and its items are priced with costItem
-- (the item the game counts the currency as) and costCount.
--
-- Professions list one encounter per recipe, lowest skill first:
--     { id = "S3919", name = "Rough Dynamite", spellID = 3919,
--       skill = { 1, 30, 45, 60 },      -- orange, yellow, green, gray
--       learned = "Trainer",            -- optional; note = "Gnomish" for specializations
--       gather = 245,                   -- Mining only: skill to mine the ore it smelts
--       loot = {
--           { itemID = 4358, count = 2 },              -- the product (count when > 1)
--           { itemID = 10601, recipe = true, cost = 1200 }, -- recipe item that teaches it
--       },
--       reagents = { { itemID = 4357, count = 2 } } }
-- Enchants make no item: their loot has only recipe items, and the UI shows
-- the spell itself. Items that only need the skill to use (note = "use") and
-- gathered herbs and fish have skill = { required } or none, and no spellID.
--
-- Dungeon quests (Quests.lua, also generated) are registered per dungeon:
--     ns.Data:RegisterQuests("DEADMINES", {
--         { id = 166, name = "The Defias Brotherhood", side = "Alliance", -- side: none = both
--           level = 22, minLevel = 14, money = 700,                      -- money in copper
--           xp = 2600,                                                   -- full XP, as the game pays it: nil = not
--                                                                        -- confirmed yet, 0 = pays none
--           giver = "Gryan Stoutmantle", classes = "Paladin",            -- classes: class quests only
--           giverNpc = 234,                                              -- giver's NPC ID, when it has a map spot
--           startsFrom = "An Unsent Letter",                             -- an item starts it (giver drops it)
--           providedItem = "Treaty of Understanding", providedItemId = 1,  -- no known giver: the item it hands over
--           chainStart = 65, chainStartName = "The Defias Brotherhood",  -- first quest of its chain,
--           chainGiver = "Gryan Stoutmantle", chainStep = 7,             -- and this quest's place in it
--           chainGiverNpc = 234,                                         -- or chainStartItem = "An Unsent Letter"
--           choice = { 6087, 2041 }, rewards = { 1893 },                 -- pick one; always given
--           objective = "Kill Edwin VanCleef ...",                       -- quest text; $N, $C, $R, $G filled in for the player
--           alt = { 4603, 4604 } },                                      -- other IDs of the same quest
--     })
-- A quest the game offers again each week has weekly = true. A currency
-- list whose vendor gives quests (the Tarnished Undermine Real's "In Demand"
-- quests) registers them the same way under its own ID, in its own file.
-- and the givers' map spots: ns.Data:RegisterNpcs({ [234] = { 1436, 56.2, 47.4, 0, -10510, 1046 } })
-- (uiMapID, x and y in percent on that zone's map, then the continent and
-- world x and y when known, which the game turns into a spot on its own map:
-- the few spots from Wowhead are on its maps, not always the game's). A
-- negative ID is an object that starts a quest (a Venom Bottle), not an NPC.
-- An NPC standing in a different place for each quest (a warlock's summoned
-- demon, by each city's trainer) has its spot per quest instead:
-- ns.Data:RegisterQuestSpots({ [1471] = { [5676] = { 1458, 86.4, 26.4 } } }),
-- read with ns.Data:NpcSpot(npc, questID).
-- The mobs most likely to drop a quest's starting item (startsFrom, or
-- providedItem) are droppers = { { name = "Defias Pirate", npc = 657 }, ... },
-- and chainDroppers for the chain's first item; npc only with a map spot,
-- inside = instance ID when they're in another dungeon. fromObject = true marks
-- a startsFrom or providedItem looted from a chest or object in the dungeon.
-- Givers inside a dungeon carry giverInside / chainGiverInside = instance ID.
-- A quest each side takes from its own NPCs (The Islander: every city's
-- warrior trainer) lists them all as givers = { { npc = 3041, name = "Torm
-- Ragetotem", side = "Horde" }, ... } (side: none = serves both), and
-- chainGivers for its chain's first quest; giver and chainGiver then name
-- the one of the player's side standing nearest (UI/Lists.lua).
-- Every dungeon's and raid's entrance (Data/Entrances.lua) is a spot of the
-- same shape (percent may be nil):
--     ns.Data:RegisterEntrances({ BRD = { 1428, 29.1, 23.2, 0, -7494.9, -1123.5 } })
-- Every dungeon and raid gets an "Overview" entry ahead of its encounters,
-- which the UI shows as its facts, in its own row above the "Quests" (dungeons
-- only) and "Encounters" groups in the middle column. A collection with
-- quests lists them in a "Quests" group above its sections, there under "Vendor".
local _, ns = ...
local L = ns.L

ns.Data = { instances = {}, byCategory = {}, quests = {}, npcs = {}, questSpots = {}, entrances = {}, attunements = {},
            itemChains = {}, maps = {},
            recipeSources = {}, recipeTrainers = { trainers = {}, recipes = {} }, scarce = {}, bosses = {},
            abilities = {}, observed = {}, questNames = {}, questItems = {},
            questStarts = {}, chains = {}, chainsOf = {}, chainSteps = {},
            optionalLeadIns = {}, breadcrumbs = {}, classQuests = {}, classSpells = {},
            classQuestFolds = {}, classRecipes = {}, reagentVendors = { vendors = {}, items = {} },
            knownVendorRecipes = {}, knownVendorSets = {}, vendorPairs = {},
            vendorItems = { vendors = {}, items = {}, commonStock = {} }, foodBuffs = {}, portals = {} }

ns.Data.CATEGORIES = { "DUNGEON", "RAID", "PVP", "FACTION", "COLLECTION", "PROFESSION" }

-- Encounters that aren't a boss: the Overview page and the loot pools.
local NOT_BOSSES = { OVERVIEW = true, TRASH = true, SHARED = true }

function ns.Data:Register(instance)
    assert(instance.id and instance.category, "instance needs id and category")
    if instance.category == "DUNGEON" or instance.category == "RAID" then
        table.insert(instance.encounters, 1, { id = "OVERVIEW", name = L["Overview"], overview = true, loot = {} })
    end
    self.instances[instance.id] = instance
    local list = self.byCategory[instance.category] or {}
    self.byCategory[instance.category] = list
    table.insert(list, instance)
end

-- A quest whose earlier steps differ by side keeps each side's chain fields
-- under bySide = { Alliance = { chainStart = ..., chain = { ... } }, Horde = ... };
-- the player's side is copied onto the quest once the game knows it.
local sideChains = {}
local function TakeSide(quests)
    local side = UnitFactionGroup("player")
    if side ~= "Alliance" and side ~= "Horde" then return false end
    for _, quest in ipairs(quests) do
        for key, value in pairs(quest.bySide and quest.bySide[side] or {}) do quest[key] = value end
    end
    return true
end

function ns.Data:RegisterQuests(instanceID, quests)
    self.quests[instanceID] = quests
    if not TakeSide(quests) then sideChains[#sideChains + 1] = quests end
end

-- In Classic a quest pays its full XP to a player at most this many levels
-- above it, and less the higher above that (80% at six over, down to 10%).
local FULL_XP_LEVELS_ABOVE = 5

-- Whether a player of `playerLevel` gets a quest's full XP; false when
-- either level isn't known (a quest's level is above 0 when it is), as
-- scraper/needroll_scraper/questxp.py pays_full_xp.
function ns.Data:PaysFullXP(questLevel, playerLevel)
    if type(questLevel) ~= "number" or questLevel <= 0 or type(playerLevel) ~= "number" then return false end
    return playerLevel <= questLevel + FULL_XP_LEVELS_ABOVE
end

-- The XP the game offers for one quest in the player's quest log, or nil
-- when it isn't in the log or the game says 0 (the level cap pays none).
local function QuestLogXP(questID)
    if not C_QuestLog.IsOnQuest(questID) then return nil end
    local xp = ns.Plain(GetQuestLogRewardXP(questID))
    if type(xp) ~= "number" or xp <= 0 then return nil end
    return xp
end

-- A quest's full XP for its Rewards: the game's own number while the quest
-- (under any of its IDs) is in the player's quest log and the player is
-- within full-XP range of it, else the confirmed number the data carries
-- (nil: not confirmed yet, 0: pays none). Above that range the game offers
-- this character less than the quest's full XP, so its number isn't used.
function ns.Data:QuestXP(quest)
    if not self:PaysFullXP(quest.level, ns.PlayerLevel()) then return quest.xp end
    local live = QuestLogXP(quest.id)
    for _, altID in ipairs(quest.alt or {}) do
        live = live or QuestLogXP(altID)
    end
    return live or quest.xp
end

-- The game's answer to whether a quest in the player's quest log can be
-- shared with the party, or nil when it isn't in the log.
local function QuestLogShareable(questID)
    if not C_QuestLog.IsOnQuest(questID) then return nil end
    return C_QuestLog.IsPushableQuest(questID) and true or false
end

-- The game's answer while the quest (under any of its IDs) is in the log,
-- else the data's: the scraper's `shareable` from forever.json or QuestieDB's
-- quest flags, left out where no source knows.
local function FreshShareable(quest)
    local live = QuestLogShareable(quest.id)
    if live ~= nil then return live end
    for _, altID in ipairs(quest.alt or {}) do
        live = QuestLogShareable(altID)
        if live ~= nil then return live end
    end
    return quest.shareable
end

-- Each quest's answer is kept until the quest log changes, wrapped in a
-- table so an unknown (nil) one is kept too: the Quests list asks on every
-- redraw, each frame of a group sliding open. ns.UI.ForgetQuestStatus
-- clears it with the quest statuses.
ns.Data.shareableCache = {}

-- Whether the player can share a quest with their party (the quest log's
-- Share button): true, false, or nil when unknown.
function ns.Data:QuestShareable(quest)
    local cached = self.shareableCache[quest]
    if not cached then
        cached = { FreshShareable(quest) }
        self.shareableCache[quest] = cached
    end
    return cached[1]
end

function ns.Data:ForgetQuestShareable()
    wipe(self.shareableCache)
end

-- Class quests (ClassQuests.lua), shaped like dungeon quests, per class
-- token (UnitClass's second return): the Classes tab's Quests section. One
-- whose targets all stand in one dungeon or raid names it, dungeon = its ID.
-- rewardsUnknown = true marks one whose rewards no source knows. Quests
-- teaching the same spell (one per city or side: the warlock's Bindings)
-- share group = that spell's ID, and the Quests section lists them as one.
function ns.Data:RegisterClassQuests(classToken, quests)
    self.classQuests[classToken] = quests
    if not TakeSide(quests) then sideChains[#sideChains + 1] = quests end
end

