-- Questlines whose WoW: Forever version isn't known yet, built from Classic
-- guides: their fold and page say they may change.
local TENTATIVE_CLASS_QUEST_FOLDS = { BENEDICTION = true, QUEL_SERRAR = true }

-- A questline's steps that aren't quests (loot an item, use one), by fold
-- key, in order: its page lists them under "Outside the quests".
local CLASS_QUEST_FOLD_ITEM_STEPS = {
    BENEDICTION = {
        L["Before the quest: loot The Eye of Divinity from Majordomo Executus in Molten Core and wear it, or Eris Havenfire stays hidden."],
        L["After it: loot The Eye of Shadow from Lord Kazzak or the demons of the Tainted Scar in the Blasted Lands."],
        L["Then use the Splinter of Nordrassil to form Benediction, which turns into Anathema and back."],
    },
}

-- A branch's name, by its label: the piece of armour it makes, the demon
-- it binds or whose orb it makes (Orb of Orahil), or the Skyborn's path
-- (Forever's race, whose race ID QuestieDB and Wowhead give differently, so
-- it isn't named by ID).
local CLASS_QUEST_BRANCH_NAMES = {
    SKYBORN = L["Skyborn"],
    COIF = L["Coif"],
    GAUNTLETS = L["Gauntlets"],
    HELM = L["Helm"],
    LEGGINGS = L["Leggings"],
    LEGGUARDS = L["Legguards"],
    SUCCUBUS = L["Succubus"],
    INCUBUS = L["Incubus"],
    DAR_ORAHIL = L["Dar'Orahil"],
    NOH_ORAHIL = L["Noh'Orahil"],
}

-- What a fold's second stage (its followUp) rewards, by its label, for the
-- questline page's "Rewards a weapon of your choice".
local CLASS_QUEST_REWARD_NAMES = {
    WEAPON = L["a weapon of your choice"],
}

-- A step of a fold is a quest ID, or a version step: a list of quest IDs,
-- one step done by any one of them (the city copies of one breadcrumb,
-- Gakin's Summons or The Slaughtered Lamb). The quests of step `step`.
local function StepQuestIDs(step)
    return type(step) == "table" and step or { step }
end

-- The lists of steps of `stage` (a fold, or its followUp): its steps, its
-- finish and each branch's quests.
local function StageStepLists(stage)
    local lists = { stage.steps or {}, stage.finish or {} }
    for _, branch in ipairs(stage.branches or {}) do table.insert(lists, branch.quests) end
    return lists
end

-- The last step of `steps` that isn't optional (fold.isOptional), or nil.
local function LastRequiredStep(steps, isOptional)
    for index = #steps, 1, -1 do
        if not isOptional[StepQuestIDs(steps[index])[1]] then return steps[index] end
    end
end

-- The steps that end one stage of a fold (the fold itself, or its
-- followUp): its finish's last, else each branch's last, else its steps'
-- last, an optional step never one (the scraper's stage_ends goes by the same).
local function StageEnds(stage, isOptional)
    if stage.finish then return { LastRequiredStep(stage.finish, isOptional) } end
    if not stage.branches then return { LastRequiredStep(stage.steps, isOptional) } end
    local ends = {}
    for _, branch in ipairs(stage.branches) do table.insert(ends, LastRequiredStep(branch.quests, isOptional)) end
    return ends
end

-- Marks every quest of version step `step` optional in `isOptional` when
-- any of them is.
local function SpreadOptional(isOptional, step)
    local questIDs = StepQuestIDs(step)
    local anyOptional = false
    for _, questID in ipairs(questIDs) do anyOptional = anyOptional or isOptional[questID] == true end
    for _, questID in ipairs(questIDs) do isOptional[questID] = anyOptional or nil end
end

-- Fills fold.isOptional (quest ID -> true) from its optional list: the
-- lead-ins and retries a player may skip. A version step counts as
-- optional whole when any of its quests is.
local function MarkOptional(fold)
    fold.isOptional = {}
    for _, questID in ipairs(fold.optional or {}) do fold.isOptional[questID] = true end
    for _, stage in ipairs({ fold, fold.followUp }) do
        for _, steps in ipairs(StageStepLists(stage)) do
            for _, step in ipairs(steps) do SpreadOptional(fold.isOptional, step) end
        end
    end
end

-- Points each quest of `stage`, a stage of `fold`, back at them in
-- `foldOf` (quest ID -> { fold, stage, isEnd, versionGroup }): a version
-- step's quests share versionGroup, so the quests list them as one entry.
local function MapStageQuests(foldOf, fold, stage)
    for _, steps in ipairs(StageStepLists(stage)) do
        for _, step in ipairs(steps) do
            local versionGroup = type(step) == "table" and fold.key .. ":" .. step[1] or nil
            for _, questID in ipairs(StepQuestIDs(step)) do
                foldOf[questID] = { fold = fold, stage = stage, isEnd = false, versionGroup = versionGroup }
            end
        end
    end
    for _, step in ipairs(StageEnds(stage, fold.isOptional)) do
        for _, questID in ipairs(StepQuestIDs(step)) do foldOf[questID].isEnd = true end
    end
end

-- Gives each labelled branch of `stage` (a fold, or its followUp) its labelName.
local function NameBranches(stage)
    for _, branch in ipairs(stage.branches or {}) do
        branch.labelName = branch.label and (CLASS_QUEST_BRANCH_NAMES[branch.label] or branch.label)
    end
end

-- Questlines the Classes tab's Quests section lists under a fold of their
-- own, each with a questline page (ClassQuests.lua, after the class's
-- quests): { key, steps = { step, ... } (done first, in order),
-- branches = { { quests = { step, ... }, label = key or nil, races = {
-- race ID, ... } or nil }, ... } (done after the steps, in any order; with
-- oneOf, alternatives of which one is done: one per race, city or side),
-- finish = { step, ... } (done after the branches), after = the quest
-- of another questline done first, teaches = { { spell = ID, rank = n or
-- nil }, ... }, optional = { quest ID, ... } (lead-ins and retries a player
-- may skip), followUp = a second stage done after the rest: { oneOf,
-- label = what it rewards (WEAPON), steps, branches, finish } }; any part
-- can be missing. A step is a quest ID, or a version step: { quest ID, ...
-- }, done by any one of them. Each fold gets its name, isOptional
-- (MarkOptional), its followUp a key of its own and what it rewards
-- (labelName), each labelled branch its labelName. Its quests point back to
-- it and their stage by ID; the quests that end each stage (isEnd) are the
-- ones the class's quest count and Overview go by.
function ns.Data:RegisterClassQuestFolds(classToken, folds)
    local foldOf = {}
    for _, fold in ipairs(folds) do
        fold.name = CLASS_QUEST_FOLD_NAMES[fold.key] or fold.key
        fold.isTentative = TENTATIVE_CLASS_QUEST_FOLDS[fold.key]
        fold.itemSteps = CLASS_QUEST_FOLD_ITEM_STEPS[fold.key]
        MarkOptional(fold)
        NameBranches(fold)
        MapStageQuests(foldOf, fold, fold)
        local followUp = fold.followUp
        if followUp then
            followUp.key = fold.key .. ":FOLLOW_UP"
            followUp.labelName = followUp.label and (CLASS_QUEST_REWARD_NAMES[followUp.label] or followUp.label)
            NameBranches(followUp)
            MapStageQuests(foldOf, fold, followUp)
        end
    end
    self.classQuestFolds[classToken] = foldOf
end

-- Each class's trainer spells and trainers (ClassSpells.lua), per class
-- token: the Classes tab's Abilities section and Overview page.
-- { tabs = { tab key, ... }, trainers = { ... }, spells = { ... } }, each
-- trainer { npc = NPC ID, name, side (nil: serves both sides), tab (the one
-- tab they teach, the mage's portal trainers) } with its map spot in
-- self.npcs, each spell { tab = ..., ranks = { { spellID, level, copper }, ... },
-- first = "quest" or "talent" (rank 1 is { spellID } alone, not trained),
-- side = "Alliance" or "Horde" (only that side's trainers teach it) }.
function ns.Data:RegisterClassSpells(classToken, classSpells)
    self.classSpells[classToken] = classSpells
end

ns:On("PLAYER_LOGIN", function()
    for _, quests in ipairs(sideChains) do TakeSide(quests) end
    sideChains = {}
end)

-- Hand-kept fixes to where dungeon quests start (Data/QuestStarts.lua):
-- instance ID = { quest ID = true when it starts inside, false when not, or
-- a table naming who or where inside starts it }.
function ns.Data:RegisterQuestStarts(starts)
    for id, quests in pairs(starts) do
        self.questStarts[id] = self.questStarts[id] or {}
        for quest, inside in pairs(quests) do self.questStarts[id][quest] = inside end
    end
end

-- A dungeon quest's hand-kept start: whether it starts inside (nil when
-- nothing is kept for it), and the start that replaces the scraped one (a
-- table: giver, or where its item is looted) or nil.
function ns.Data:QuestStart(instanceID, questID)
    local kept = self.questStarts[instanceID]
    kept = kept and kept[questID]
    if type(kept) == "table" then return kept.inside ~= false, kept end
    return kept, nil
end

-- Whether id is in ranges written as first, last, first, last, ... in
-- rising order (a binary search over the ranges' first IDs).
local function InRanges(spans, id)
    local lo, hi = 1, #spans / 2
    while lo <= hi do
        local mid = math.floor((lo + hi) / 2)
        if id < spans[mid * 2 - 1] then
            hi = mid - 1
        elseif id > spans[mid * 2] then
            lo = mid + 1
        else
            return true
        end
    end
    return false
end

-- Every quest NeedRoll knows (Data/KnownQuests.lua), as ranges: first,
-- last, first, last, ... in rising order. Core/Drops.lua reports quests
-- missing from it, the ones new in WoW: Forever.
local knownQuests = {}
function ns.Data:RegisterKnownQuests(spans)
    knownQuests = spans
end

-- Whether the quest is in Data/KnownQuests.lua.
function ns.Data:KnownQuest(questID)
    return InRanges(knownQuests, questID)
end

-- Boss drops NeedRoll knows beyond its loot lists (Data/KnownDrops.lua):
-- world drops as ranges of item IDs (known from any creature), and each
-- NPC's other known drops as a list of item IDs. Core/Drops.lua shares
-- only the drops neither these nor the loot lists have.
local knownWorld, knownByNpc, knownSets = {}, {}, {}
function ns.Data:RegisterKnownDrops(world, byNpc)
    knownWorld, knownByNpc, knownSets = world, byNpc, {}
end

-- The dungeon and raid loot lists by boss: { any = { [itemID] = true },
-- byNpc = { [npcID] = { [itemID] = true } } }. Every item of an encounter
-- counts for each of its NPCs. Built on first use.
function ns.Data:ListedDrops()
    if self.listedDrops then return self.listedDrops end
    local listed = { any = {}, byNpc = {} }
    for _, category in ipairs({ "DUNGEON", "RAID" }) do
        for _, instance in ipairs(self:List(category)) do
            for _, encounter in ipairs(instance.encounters) do
                local npcs = {}
                if encounter.npc then npcs[#npcs + 1] = encounter.npc end
                for _, boss in ipairs(self:Bosses(instance, encounter) or {}) do
                    if boss[5] then npcs[#npcs + 1] = boss[5] end
                end
                for _, entry in ipairs(encounter.loot or {}) do
                    local id = entry.itemID
                    if id then
                        listed.any[id] = true
                        for _, npc in ipairs(npcs) do
                            listed.byNpc[npc] = listed.byNpc[npc] or {}
                            listed.byNpc[npc][id] = true
                        end
                    end
                end
            end
        end
    end
    self.listedDrops = listed
    return listed
end

-- Whether NeedRoll already knows the creature drops the item: a world drop,
-- one of its known drops in Data/KnownDrops.lua, or in its loot list.
function ns.Data:KnownDrop(npcID, itemID)
    if not (npcID and itemID) then return false end
    if InRanges(knownWorld, itemID) then return true end
    local set = knownSets[npcID]
    if not set and knownByNpc[npcID] then
        set = {}
        for _, id in ipairs(knownByNpc[npcID]) do set[id] = true end
        knownSets[npcID] = set
    end
    if set and set[itemID] then return true end
    local listed = self:ListedDrops().byNpc[npcID]
    return listed ~= nil and listed[itemID] == true
end

-- Recipe items each vendor is known to sell (Data/KnownVendorRecipes.lua):
-- NPC ID -> its recipe item IDs, in rising order (knownVendorRecipes), and
-- each vendor's as a set once asked about (knownVendorSets). Core/Vendors.lua
-- shares the recipes a vendor's window offers that aren't on its list.
function ns.Data:RegisterKnownVendorRecipes(byNpc)
    self.knownVendorRecipes, self.knownVendorSets = byNpc, {}
end

-- Whether Data/KnownVendorRecipes.lua says vendor `npcID` sells recipe item `itemID`.
function ns.Data:KnownVendorRecipe(npcID, itemID)
    local itemIDs = self.knownVendorRecipes[npcID]
    if not itemIDs then return false end
    if not self.knownVendorSets[npcID] then
        local set = {}
        for _, id in ipairs(itemIDs) do set[id] = true end
        self.knownVendorSets[npcID] = set
    end
    return self.knownVendorSets[npcID][itemID] == true
end

--[==[@debug@
-- The recipe items Data/KnownVendorRecipes.lua says vendor `npcID` sells
-- (none for a vendor it doesn't list), for Core/Vendors.lua's dev check.
function ns.Data:KnownVendorRecipeIDs(npcID)
    return self.knownVendorRecipes[npcID] or {}
end
--@end-debug@]==]

-- Every item a profession list has: the recipe items that teach its
-- recipes, the fishing books, and what its recipes make. Built on first use.
function ns.Data:ProfessionItems()
    if self.professionItems then return self.professionItems end
    local items = {}
    for _, instance in ipairs(self:List("PROFESSION")) do
        for _, encounter in ipairs(instance.encounters) do
            for _, entry in ipairs(encounter.loot or {}) do
                if entry.itemID then items[entry.itemID] = true end
            end
        end
    end
    self.professionItems = items
    return items
end

-- Quest prints (Data/KnownQuests.lua), for spotting quests WoW: Forever
-- changed (Core/Drops.lua). The 1.12 quests' come as one string, 3
-- characters per quest ID from `first` on: the level and a hash of the
-- reward items; kept as the lines given and joined on first use. The
-- confirmed full XP of every quest NeedRoll lists (1.12 or new in Forever)
-- comes as quest ID = XP, the same numbers its pages show.
local PRINT_ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz+*"
local NOT_A_QUEST, NOT_COMPARED = 126, 46 -- the bytes of "~" (the whole print) and "." (the level)
local printsFirst, printLines, prints, printedXP = 1, nil, "", {}
function ns.Data:RegisterQuestPrints(first, lines, xpByQuest)
    printsFirst, printLines, prints, printedXP = first, lines, nil, xpByQuest or {}
end

-- The 1.12 quest's level (nil when not compared) and reward hash, from
-- the string of 1.12 prints; nil when the quest isn't a 1.12 quest.
local function ClassicQuestPrint(questID)
    if not prints then prints, printLines = table.concat(printLines or {}), nil end
    local at = (questID - printsFirst) * 3 + 1
    if at < 1 or at + 2 > #prints then return nil end
    local levelChar, hi, lo = prints:byte(at, at + 2)
    if levelChar == NOT_A_QUEST then return nil end
    local level = levelChar ~= NOT_COMPARED and PRINT_ALPHABET:find(string.char(levelChar), 1, true) - 1 or nil
    hi = PRINT_ALPHABET:find(string.char(hi), 1, true) - 1
    lo = PRINT_ALPHABET:find(string.char(lo), 1, true) - 1
    return level, hi * 64 + lo
end

-- A quest's print: { level, rewardHash, xp }, each nil when it isn't
-- compared (only 1.12 quests have a level and reward hash; xp is the
-- confirmed full XP); nil when NeedRoll has no print of the quest.
function ns.Data:QuestPrint(questID)
    local level, rewardHash = ClassicQuestPrint(questID)
    local xp = printedXP[questID]
    if not (rewardHash or xp) then return nil end
    return { level = level, rewardHash = rewardHash, xp = xp }
end

-- The names of quests earlier in a dungeon quest's chain (Data/Quests.lua):
-- quest ID = name.
function ns.Data:RegisterQuestNames(names)
    for id, name in pairs(names) do self.questNames[id] = name end
end

-- The runs of quests a step of Data/Chains.lua holds, each a list of quest
-- IDs done in order: one run per quest of a step to choose from (a quest,
-- or a table of several), and per member of a step whose quests are all
-- needed ({ all = { { 544, 545 }, 93680 } }: 544 then 545, and 93680).
local function StepRuns(step)
    local runs = {}
    if type(step) ~= "table" then return { { step } } end
    for _, member in ipairs(step.all or step) do
        runs[#runs + 1] = type(member) == "table" and member or { member }
    end
    return runs
end

-- Whole quest chains (Data/Chains.lua): each lists its quests in order; a
-- table among them is one step of several quests (one per class, or a
-- choice of reward quests: any one of them does), or with `all` one whose
-- quests are all needed, in any order, each of its members a quest or a run
-- of quests done in order; side = the only side the chain is for; optional =
-- its lead-ins a player may skip (Seeking Caitlin); breadcrumbs = its
-- breadcrumbs, lead-ins a player may skip too (Trouble in the Deeps).
function ns.Data:RegisterChains(chains)
    for _, chain in ipairs(chains) do
        local chainIndex = #self.chains + 1
        self.chains[chainIndex] = chain
        for _, questID in ipairs(chain.optional or {}) do self.optionalLeadIns[questID] = true end
        for _, questID in ipairs(chain.breadcrumbs or {}) do
            self.optionalLeadIns[questID] = true
            self.breadcrumbs[questID] = true
        end
        for _, step in ipairs(chain) do
            for _, run in ipairs(StepRuns(step)) do
                for _, id in ipairs(run) do
                    local list = self.chainsOf[id] or {}
                    list[#list + 1] = chainIndex
                    self.chainsOf[id] = list
                end
            end
        end
    end
end

-- Whether quest `questID` is a chain's lead-in a player may skip (one of its
-- optional or breadcrumbs): drawn as optional and left out of a questline's
-- progress.
function ns.Data:IsOptionalLeadIn(questID)
    return self.optionalLeadIns[questID] == true
end

-- Whether quest `questID` is a chain's breadcrumb (its `breadcrumbs`): an
-- optional lead-in whose only job is to send the player to the next
-- quest's giver, drawn as a signpost rather than a quest of the chain.
function ns.Data:IsBreadcrumb(questID)
    return self.breadcrumbs[questID] == true
end

-- What a chain step is (Data/Chains.lua, written by the scraper's
-- chains.py): id = { name, level, minLevel, side, classes, giver, giverNpc,
-- giverInside, givers, startItem, startItemId, droppers (what drops or holds
-- its starting item), turnIn, turnInNpc, turnInInside, zone (an AreaTable
-- ID), kills, loot, named, objective }, the places in the same fields
-- Data/Quests.lua uses.
function ns.Data:RegisterChainSteps(steps)
    for id, step in pairs(steps) do self.chainSteps[id] = step end
end

-- Whether a step's quest is one `side` and `class` (UnitClass's second
-- return) can take; nil side or class takes any.
local function StepFits(step, side, class)
    if not step then return true end
    if side and step.side and step.side ~= side then return false end
    if class and step.classes then
        for _, stepClass in ipairs(step.classes) do
            if stepClass == class then return true end
        end
        return false
    end
    return true
end

-- Whether chain step quest `questID` is one `side` and `class` can take
-- (true for a quest Data/Chains.lua doesn't describe).
function ns.Data:StepFits(questID, side, class)
    return StepFits(self.chainSteps[questID], side, class)
end

-- The chains quest `questID` is on that `side` (optional) can take, by
-- their index in self.chains, in the order Data/Chains.lua lists them.
function ns.Data:ChainsWith(questID, side)
    local found = {}
    for _, chainIndex in ipairs(self.chainsOf[questID] or {}) do
        local chainSide = self.chains[chainIndex].side
        if not (side and chainSide and chainSide ~= side) then found[#found + 1] = chainIndex end
    end
    return found
end

-- The runs of `runs` (StepRuns) with only the quests `side` and `class`
-- can take, except `keptID`; a run with none left is dropped.
local function FittingRuns(runs, side, class, keptID)
    local fitting = {}
    for _, run in ipairs(runs) do
        local ids = {}
        for _, id in ipairs(run) do
            if id == keptID or StepFits(ns.Data.chainSteps[id], side, class) then ids[#ids + 1] = id end
        end
        if #ids > 0 then fitting[#fitting + 1] = ids end
    end
    return fitting
end

-- Chain `chainIndex` (of self.chains) for `side` and `class` (both
-- optional): a list of steps, each a list of quest IDs: one, or several to
-- choose from; or for a step whose quests are all needed, every one of them
-- in order, with `all` its members, each a list of quest IDs done in order.
-- Quests the side or class can't take are dropped, except `keptID`
-- (optional); a step none of whose quests fit keeps them all.
function ns.Data:FittingChain(chainIndex, side, class, keptID)
    local steps = {}
    for _, step in ipairs(self.chains[chainIndex]) do
        local runs = StepRuns(step)
        local fitting = FittingRuns(runs, side, class, keptID)
        if #fitting == 0 then fitting = runs end
        local ids = {}
        for _, run in ipairs(fitting) do
            for _, id in ipairs(run) do ids[#ids + 1] = id end
        end
        if type(step) == "table" and step.all then ids.all = fitting end
        steps[#steps + 1] = ids
    end
    return steps
end

-- How far along chain step `ids` (FittingChain's) is: how many of the
-- quests it needs are done (IsQuestDone(questID) tells) and how many it
-- needs: one of a step to choose from, every one of a step whose quests
-- are all needed.
function ns.Data:ChainStepProgress(ids, IsQuestDone)
    local doneCount = 0
    for _, id in ipairs(ids) do
        if IsQuestDone(id) then doneCount = doneCount + 1 end
    end
    if ids.all then return doneCount, #ids end
    return math.min(doneCount, 1), 1
end

-- The step numbers of chain `steps` (FittingChain's), as the questline
-- page, its fold and the quest page show them: numbers count steps, not
-- quests (a step of several quests is one number), and a lead-in a player
-- may skip has none. Returns each step's number by its index (nil for a
-- lead-in) and how many numbered steps there are.
function ns.Data:StepNumbers(steps)
    local numbers, count = {}, 0
    for index, ids in ipairs(steps) do
        if not self:IsOptionalLeadIn(ids[1]) then
            count = count + 1
            numbers[index] = count
        end
    end
    return numbers, count
end

-- The index of chain `steps`' step to do next (IsQuestDone(questID) tells
-- which quests are done): the one after the last step done (a step done
-- means those before it were, whatever the game flags), or the last one
-- partway done (a step whose quests are all needed, with some of them
-- done), passing lead-ins a player may skip. Nil when every step is done.
-- The world map's questline markers and the Next step box of a dungeon's
-- questline page both go by it.
function ns.Data:NextStepIndex(steps, IsQuestDone)
    local nextIndex = 1
    for index, ids in ipairs(steps) do
        local doneCount, neededCount = self:ChainStepProgress(ids, IsQuestDone)
        if doneCount == neededCount then
            nextIndex = index + 1
        elseif doneCount > 0 then
            nextIndex = index
        end
    end
    while steps[nextIndex] and self:IsOptionalLeadIn(steps[nextIndex][1]) do nextIndex = nextIndex + 1 end
    return steps[nextIndex] and nextIndex or nil
end

-- The quests of chain step `ids` the character can pick up: any of a step
-- to choose from; of a step whose quests are all needed, the first not done
-- of each member not finished yet (Dalaran Patrols once Prison Break In is
-- done, and Key to the City), in the step's order.
function ns.Data.QuestsToPickUp(ids, IsQuestDone)
    if not ids.all then return ids end
    local toPickUp = {}
    for _, run in ipairs(ids.all) do
        for _, id in ipairs(run) do
            if not IsQuestDone(id) then
                table.insert(toPickUp, id)
                break
            end
        end
    end
    return toPickUp
end

-- The whole chain `questID` is on, for `side` and `class` (both optional):
-- its steps (FittingChain) and the place of `questID` in it. The longest
-- chain wins when the quest is on several. nil when it's on none.
function ns.Data:Chain(questID, side, class)
    local best
    for _, chainIndex in ipairs(self:ChainsWith(questID, side)) do
        if not best or #self.chains[chainIndex] > #self.chains[best] then best = chainIndex end
    end
    if not best then return nil end
    local steps, at = self:FittingChain(best, side, class, questID), nil
    for index, ids in ipairs(steps) do
        for _, id in ipairs(ids) do
            if id == questID then at = index end
        end
    end
    return steps, at
end

-- A raid's attunement (Data/Attunements.lua): its quests in order, shaped
-- like dungeon quests, under `both` when either side does the same steps,
-- else under `Alliance` and `Horde`; `none = true` when anyone can walk in;
-- `note` is a line shown above the steps.
function ns.Data:RegisterAttunement(instanceID, attunement)
    self.attunements[instanceID] = attunement
end

-- The raid's attunement, or nil when it isn't known.
function ns.Data:Attunement(instanceID)
    return self.attunements[instanceID]
end

-- An instance's item chains (Data/ItemChains.lua): what its page shows
-- under an item's own heading, beside a raid's attunement (a dungeon's key,
-- Aqual Quintessence). Each is { item = the item ID whose name heads it,
-- name = that name in English, note, and steps under both, Alliance or
-- Horde as an attunement's }. A step is a quest, or { all = { ... } } when
-- every member is needed, in any order: a member is a quest or a list of
-- quests done in order.
function ns.Data:RegisterItemChains(instanceID, chains)
    self.itemChains[instanceID] = chains
end

-- The instance's item chains, in order; empty when it has none.
function ns.Data:ItemChains(instanceID)
    return self.itemChains[instanceID] or {}
end

-- An attunement or item chain step's quests: the quest itself, or every
-- quest of an all-of step's members, in order.
function ns.Data:StepQuests(step)
    if not step.all then return { step } end
    local quests = {}
    for _, member in ipairs(step.all) do
        for _, quest in ipairs(member.id and { member } or member) do quests[#quests + 1] = quest end
    end
    return quests
end

-- Every quest of an attunement's or item chain's steps, each side's.
function ns.Data:ChainQuests(chain)
    local quests = {}
    for _, side in ipairs({ "both", "Alliance", "Horde" }) do
        for _, step in ipairs(chain[side] or {}) do
            for _, quest in ipairs(self:StepQuests(step)) do quests[#quests + 1] = quest end
        end
    end
    return quests
end

local function Spot(spot)
    return { map = spot[1], x = spot[2] and spot[2] / 100, y = spot[3] and spot[3] / 100,
             continent = spot[4], worldX = spot[5], worldY = spot[6] }
end

-- What one Data/VendorPairs.lua entry says of its vendor: the side it
-- serves (a paired vendor is the Horde one), and for a pair the Alliance
-- partner as a vendor line takes it, { name, side, spot } (it has no NPC ID).
local function PairedVendor(pair)
    if type(pair) == "string" then return pair, nil end
    return "Horde", { name = pair[1], side = "Alliance", spot = Spot({ pair[2], pair[3], pair[4] }) }
end

-- Many data files register the spots of the NPCs they link to. The last one
-- loaded would win, so the scraper gives an NPC the same spot in every file
-- (scraper/needroll_scraper/npcspots.py; tests/smoke/modules/Data-Data.lua).
function ns.Data:RegisterNpcs(npcs)
    for id, spot in pairs(npcs) do self.npcs[id] = Spot(spot) end
end

function ns.Data:RegisterQuestSpots(questSpots)
    for questID, spots in pairs(questSpots) do
        self.questSpots[questID] = self.questSpots[questID] or {}
        for npc, spot in pairs(spots) do self.questSpots[questID][npc] = Spot(spot) end
    end
end

-- Where an NPC (negative: an object) stands for quest `questID`: its spot for
-- that quest, else its one spot for every quest. nil when neither is known.
function ns.Data:NpcSpot(npc, questID)
    if not npc then return nil end
    local forQuest = questID and self.questSpots[questID]
    return forQuest and forQuest[npc] or self.npcs[npc]
end

-- The hunter's tameable beasts and pet trainers (HunterPets.lua): the
-- Classes tab's Pets section. { families = { [creature family ID] = { diet =
-- { food key, ... }, abilities = { rank 1 spell ID, ... } } }, beasts = { {
-- npc, name, family, levels = { lowest, highest }, rank (nil: normal; 1
-- elite, 2 rare elite, 4 rare), spots, teaches = { the spell IDs of the
-- ranks it teaches } (nil: none) } }, abilities = { { allPets, trainer
-- (pet trainers sell it), ranks = { { spellID, pet level, copper }, ... } }
-- }, trainers = { { npc, name, side } } } (the trainers' map spots in
-- self.npcs). A beast's spots, one per zone it
-- spawns in, most spawns first, become map spots like self.npcs' with
-- `spawns`, how many of the beast spawn in that zone.
function ns.Data:RegisterHunterPets(pets)
    for _, beast in ipairs(pets.beasts) do
        for i, spot in ipairs(beast.spots) do
            beast.spots[i] = Spot({ spot[1], spot[2], spot[3] })
            beast.spots[i].spawns = spot[4]
        end
    end
    self.hunterPets = pets
end

-- The mage's scrolls (Data/MageScrolls.lua): the Classes tab's
-- Comprehension section. Given as { { itemID, required level or nil }, ... }
-- and kept as { itemID = ..., level = ... }, in the file's order.
function ns.Data:RegisterMageScrolls(scrolls)
    self.mageScrolls = {}
    for _, scroll in ipairs(scrolls) do
        table.insert(self.mageScrolls, { itemID = scroll[1], level = scroll[2] })
    end
end

-- The warlock's demons and demon trainers (WarlockPets.lua): the Classes
-- tab's Pets section on a warlock. { demons = { { key, family (creature
-- family ID), summon (spell ID), level, quests = { quest ID, ... },
-- abilities = { { ranks = { { the pet's spellID, level, copper, grimoire
-- itemID }, ... } } } } }, trainers = { { npc, name, side, grimoires = {
-- itemID, ... } } } } (the trainers' map spots in self.npcs). A rank with
-- no grimoire comes with the demon, for nothing.
function ns.Data:RegisterWarlockPets(pets)
    self.warlockPets = pets
end

-- Rewards for quest items that drop in dungeons and raids (Data/QuestItems.lua):
-- item ID = { quest, name, side, choice = { pick one }, rewards = { always given } }.
function ns.Data:RegisterQuestItems(items)
    for id, q in pairs(items) do self.questItems[id] = q end
end

-- Where recipe items come from (Data/RecipeSources.lua): item ID =
-- { drops = { { name, npc, inside, rate }, ... }, vendors = { { name, npc, inside, side }, ... } }.
function ns.Data:RegisterRecipeSources(sources)
    for id, s in pairs(sources) do self.recipeSources[id] = s end
end

-- Who teaches each recipe (Data/RecipeTrainers.lua): trainers = { [NPC ID] =
-- { name, side } (side nil: serves both sides) }, recipes = { [recipe spell ID] =
-- { NPC ID, ... } }. Each trainer also gets its NPC ID as `npc`, so the
-- recipe page draws it like a recipe source (its map spot is in self.npcs).
function ns.Data:RegisterRecipeTrainers(found)
    for npc, trainer in pairs(found.trainers) do
        trainer.npc = npc
        self.recipeTrainers.trainers[npc] = trainer
    end
    for spellID, npcs in pairs(found.recipes) do self.recipeTrainers.recipes[spellID] = npcs end
end

-- Who sells each class recipe's reagents (Data/Poisons.lua): vendors = { [NPC ID] =
-- { name, side } (side nil: serves both sides) }, items = { [reagent item ID] =
-- { NPC ID, ... } }. Each vendor gets its NPC ID as `npc`, as trainers do, so
-- the recipe page draws it like a recipe source (its map spot is in self.npcs).
function ns.Data:RegisterReagentVendors(found)
    for npc, vendor in pairs(found.vendors) do
        vendor.npc = npc
        self.reagentVendors.vendors[npc] = vendor
    end
    for itemID, npcs in pairs(found.items) do self.reagentVendors.items[itemID] = npcs end
end

-- The mobs a recipe page names, picked from Wowhead pages saved by hand
-- (Data/RecipeDrops.lua, loaded after Data/RecipeSources.lua): item ID =
-- { drops = { { name, npc, zone, inside, rate }, ... }, world }. Each replaces
-- that recipe's drops; zone is a uiMapID, for mobs with no map spot.
function ns.Data:RegisterRecipeDrops(drops)
    for id, d in pairs(drops) do
        local s = self.recipeSources[id]
        if not s then
            s = {}
            self.recipeSources[id] = s
        end
        s.drops = d.drops
        if d.world then s.world = s.world or true end
    end
end

-- Where each companion pet comes from (Data/CompanionSources.lua, loaded
-- after the Collections lists): item ID = { drops, vendors, quests =
-- { { id, name, side, giver, giverNpc }, ... }, containers = { { itemID,
-- name }, ... }, objects = { { name, npc or zone }, ... } }, drops and
-- vendors shaped as a recipe's. Each pet on the Companions list gets its
-- sources as `petSources`, which the loot grid shows under it; a pet with
-- none saved (a crafted one: the grid finds its recipe) gets an empty table.
function ns.Data:RegisterCompanionSources(sources)
    local companions = self:Get("COMPANIONS")
    if not companions then return end
    for _, encounter in ipairs(companions.encounters) do
        for _, entry in ipairs(encounter.loot) do
            if entry.itemID then entry.petSources = sources[entry.itemID] or {} end
        end
    end
end

-- Horde and Alliance vendors selling the same recipes (Data/VendorPairs.lua,
-- loaded after Data/RecipeSources.lua): Horde vendor's NPC ID = { Alliance
-- vendor's name, uiMapID, x, y }. A recipe the Horde vendor sells lists just
-- the two of them, each tagged with their side. A vendor with no partner can
-- instead be given just their side: NPC ID = "Alliance" or "Horde". Kept as
-- vendorPairs for the items those vendors sell (ns.Data:VendorItemSellers).
function ns.Data:RegisterVendorPairs(pairs_)
    self.vendorPairs = pairs_
    for _, s in pairs(self.recipeSources) do
        for _, vendor in ipairs(s.vendors or {}) do
            local pair = vendor.npc and pairs_[vendor.npc]
            local partner
            if pair then vendor.side, partner = PairedVendor(pair) end
            if partner then
                s.vendors = { vendor, partner }
                break
            end
        end
    end
end

-- Items only a few vendors sell (Data/VendorItems.lua, loaded after every
-- other file with NPC spots): vendors = { [NPC ID] = { name, side } }, each
-- given its NPC ID as `npc` (as recipe trainers are) so Core/Names.lua can
-- put in the client's name; items = { [item ID] = { NPC ID, ..., limited =
-- { NPC ID, ... } } }; commonStock = ranges of the item IDs more vendors
-- sell. A vendor's spot from that file is kept only when no other file
-- placed the NPC: a quest giver who also sells stays where its quests put it.
function ns.Data:RegisterVendorItems(found)
    for npc, vendor in pairs(found.vendors) do vendor.npc = npc end
    for npc, spot in pairs(found.spots) do
        if not self.npcs[npc] then self.npcs[npc] = Spot(spot) end
    end
    self.vendorItems = found
end

-- Whether more than a few vendors sell item `itemID`: everyday stock,
-- which vendor reads don't share and Search doesn't list.
function ns.Data:IsCommonStock(itemID)
    return InRanges(self.vendorItems.commonStock, itemID)
end

-- Whether Data/VendorItems.lua says vendor `npcID` sells item `itemID`.
function ns.Data:KnownVendorItem(npcID, itemID)
    for _, npc in ipairs(self.vendorItems.items[itemID] or {}) do
        if npc == npcID then return true end
    end
    return false
end

-- The vendors Data/VendorItems.lua says sell item `itemID`, as a recipe
-- page's vendor lines take them: { { name, npc, side, limited }, ... },
-- new tables each call. A vendor Data/VendorPairs.lua pairs brings its
-- Alliance partner after it (see PairedVendor).
function ns.Data:VendorItemSellers(itemID)
    local sellers = {}
    local listed = self.vendorItems.items[itemID]
    if not listed then return sellers end
    local isLimited = {}
    for _, npc in ipairs(listed.limited or {}) do isLimited[npc] = true end
    for _, npc in ipairs(listed) do
        local vendor = self.vendorItems.vendors[npc]
        local pair = self.vendorPairs[npc]
        local side, partner = vendor.side, nil
        if pair then side, partner = PairedVendor(pair) end
        sellers[#sellers + 1] = { name = vendor.name, npc = npc, side = side, limited = isLimited[npc] }
        if partner then
            partner.limited = isLimited[npc]
            sellers[#sellers + 1] = partner
        end
    end
    return sellers
end

-- Scarce gathering reagents (Data/ScarceReagents.lua): { itemID, name,
-- profession, sources = { { name, skill, rate, samples }, ... } } each.
-- Each becomes an entry of its profession's "Scarce Reagents" fold-out,
-- shaped enough like a recipe to be selected, remembered and gone back to:
-- `scarce = true`, an id, no loot, and `skill` = the easiest source's.
-- Skinning has no recipes, so it gets a list of its own (after Mining)
-- when it has Scarce reagents or a guide (Data/ProfessionGuide.lua).
local SKINNING = { id = "SKINNING", name = "Skinning", category = "PROFESSION", zone = "Primary profession",
                   encounters = {} }

local function RegisterSkinning(data)
    if data.instances.SKINNING then return end
    data:Register(SKINNING)
    local list = data.byCategory.PROFESSION
    table.remove(list)
    local at = #list + 1
    for i, instance in ipairs(list) do
        if instance.id == "MINING" then at = i + 1 end
    end
    table.insert(list, at, SKINNING)
end

function ns.Data:RegisterScarce(reagents)
    for _, r in ipairs(reagents) do
        r.id = "SCARCE:" .. r.itemID
        r.scarce = true
        r.loot = {}
        local low
        for _, src in ipairs(r.sources) do
            if src.skill and (not low or src.skill < low) then low = src.skill end
        end
        r.skill = low and { low } or nil
        if r.profession == "SKINNING" then RegisterSkinning(self) end
        self.scarce[r.profession] = self.scarce[r.profession] or {}
        table.insert(self.scarce[r.profession], r)
    end
    -- Lowest skill needed first, as the recipes run, then by name.
    for _, list in pairs(self.scarce) do
        table.sort(list, function(a, b)
            local sa, sb = a.skill and a.skill[1] or 0, b.skill and b.skill[1] or 0
            if sa ~= sb then return sa < sb end
            return a.name < b.name
        end)
    end
end

-- A profession's Scarce reagents, or an empty list.
function ns.Data:Scarce(professionID)
    return self.scarce[professionID] or {}
end

-- The buffs each Cooking product gives (Data/FoodBuffs.lua): item ID = {
-- buff key, ... } ("STAMINA", "SPIRIT" ...; UI/RecipeBand.lua names them),
-- for the Cooking list's Buff box and the recipe filter.
function ns.Data:RegisterFoodBuffs(buffs)
    for itemID, keys in pairs(buffs) do self.foodBuffs[itemID] = keys end
end

-- The buffs eating item `itemID` gives, or nil for none known.
function ns.Data:FoodBuffs(itemID)
    return self.foodBuffs[itemID]
end

-- The Professions Overview's guide (Data/ProfessionGuide.lua): npcs = { [NPC
-- ID] = { name, side } }, quests = { [quest ID] = { name, level, giver,
-- turnIn, teaches, skill, side, inside, needs } }, items = { [item ID] = name
-- }, professions = { [profession list's ID] = { ranks, specs, quests, farm }
-- } (the file's comments give each part's shape). Each NPC also gets its NPC
-- ID as `npc`, as recipe trainers do (its map spot is in self.npcs). Each
-- profession with a guide gets its Overview page as
-- instance.professionOverview, an encounter outside its recipe list (the
-- Overview row above the list picks it, UI/Lists.lua).
function ns.Data:RegisterProfessionGuide(guide)
    for npc, entry in pairs(guide.npcs) do entry.npc = npc end
    if guide.professions.SKINNING then RegisterSkinning(self) end
    for professionID in pairs(guide.professions) do
        local instance = self.instances[professionID]
        if instance then
            instance.professionOverview = { id = "OVERVIEW", name = L["Overview"], professionOverview = true,
                loot = {} }
        end
    end
    self.professionGuide = guide
end

-- A profession's guide, or nil when it has none.
function ns.Data:ProfessionGuide(professionID)
    return self.professionGuide and self.professionGuide.professions[professionID]
end

-- Camp features (Data/Camping.lua): { features = { { item, allianceItem,
-- name, profession, skill, effect, scale, adds, blueprint, blueprintName },
-- ... } } (the file's comments give each field). They become the Camping
-- list, last of the profession lists: no recipes, only its Overview page,
-- which lists every feature (UI/ProfessionOverview.lua). Each profession's
-- own features are kept lowest skill first, then by name, for its Overview.
local CAMPING = { id = "CAMPING", name = "Camping", category = "PROFESSION", zone = "Camping", encounters = {},
                  camping = true }

function ns.Data:RegisterCamping(camping)
    camping.byItem, camping.byProfession, camping.names = {}, {}, {}
    for _, feature in ipairs(camping.features) do
        camping.byItem[feature.item] = feature
        camping.names[feature.item] = feature.name
        if feature.allianceItem then camping.names[feature.allianceItem] = feature.name end
        if feature.blueprint then camping.names[feature.blueprint] = feature.blueprintName end
        camping.byProfession[feature.profession] = camping.byProfession[feature.profession] or {}
        table.insert(camping.byProfession[feature.profession], feature)
    end
    for _, features in pairs(camping.byProfession) do
        table.sort(features, function(a, b)
            if a.skill ~= b.skill then return a.skill < b.skill end
            return a.name < b.name
        end)
    end
    self.camping = camping
    CAMPING.professionOverview = { id = "OVERVIEW", name = L["Overview"], professionOverview = true, loot = {} }
    self:Register(CAMPING)
end

-- Profession `professionID`'s camp features, lowest skill first; an empty list for none.
function ns.Data:CampFeatures(professionID)
    return self.camping and self.camping.byProfession[professionID] or {}
end

-- Library Books (Data/LibraryBooks.lua; the file's comments give its
-- shape), which the Library tab lists (UI/LibraryBooks.lua). Each book's
-- spots become map spots like self.npcs', and the reward quests' names join
-- self.questNames, so Core/Names.lua puts them in the player's language.
function ns.Data:RegisterLibraryBooks(library)
    for _, book in ipairs(library.books) do
        for i, spot in ipairs(book.spots) do book.spots[i] = Spot(spot) end
    end
    for _, reward in ipairs(library.rewards) do self.questNames[reward.quest] = reward.name end
    self.libraryBooks = library
end

-- Travel portals (Data/Portals.lua; the file's comments give its shape),
-- which the game's world map marks (UI/WorldMapMarkers.lua). Each portal's
-- spot becomes a map spot like self.npcs'.
function ns.Data:RegisterPortals(portals)
    for _, portal in ipairs(portals) do portal.spot = Spot(portal.spot) end
    self.portals = portals
end

function ns.Data:RegisterEntrances(entrances)
    for id, spot in pairs(entrances) do self.entrances[id] = Spot(spot) end
end

-- The instance's entrance, or nil when it isn't known.
function ns.Data:Entrance(instanceID)
    return self.entrances[instanceID]
end

-- Layout maps (Data/Maps.lua): per instance, its levels in order.
function ns.Data:RegisterMaps(maps)
    for id, map in pairs(maps) do self.maps[id] = map end
end

-- The instance's layout map, or nil when the game has none for it.
function ns.Data:Map(instanceID)
    return self.maps[instanceID]
end

-- The game's map ID for each instance (Data/Maps.lua), what
-- GetInstanceInfo() returns eighth inside it.
ns.Data.instanceMapIDs = {}
function ns.Data:RegisterInstanceMapIDs(ids)
    for id, mapID in pairs(ids) do self.instanceMapIDs[id] = mapID end
end

-- Where the player is, read once for IsPlayerInside: the instance's name in
-- lower case ("" outside one) and its map ID. Read through ns.Plain, as
-- Drops' CurrentInstance reads them, in case the game hands either back secret.
function ns.Data:PlayerWhereabouts()
    local name, _, _, _, _, _, _, mapID = GetInstanceInfo()
    return { name = (ns.Plain(name) or ""):lower(), mapID = ns.Plain(mapID) }
end

-- Whether the player (`where`, from PlayerWhereabouts) is inside `instance`:
-- by its map ID, else (the instances new in Forever, whose IDs aren't known
-- yet) by its name.
function ns.Data:IsPlayerInside(instance, where)
    local mapID = self.instanceMapIDs[instance.id]
    if mapID then return mapID == where.mapID end
    local name, here = instance.name:lower(), where.name
    return here ~= "" and (name:find(here, 1, true) or here:find(name, 1, true)) ~= nil
end

