-- The icons a map's quest markers can take (marker = { ... } in
-- RegisterMapSpots below), by the name Data/Maps.lua gives them.
ns.Data.markerIcons = {
    attack = "Crosshair_Attack_96",
    buy = "Crosshair_buy_96",
    quest = "Exclamation-up-c60",
    turnin = "Crosshair_Questturnin_96",
    repair = "Crosshair_repairnpc_96",
    escort = "gamepad-radial-icon-social-down",
    loot = "Crosshair_lootall_96",  -- where mobs drop what a quest needs or starts with
}
ns.Data.markerOrder = { "attack", "buy", "quest", "turnin", "repair", "escort", "loot" }

-- Where a layout map's entrances and floor links are (Data/Maps.lua): per
-- instance, entrance = { { level, x, y, "raid" for a raid's entrance inside
-- a dungeon }, ... }, lock = { { level, x, y }, ... } (doors that need a key
-- or lockpicking) and links = { [level] = { { level it leads to, x, y }, ... } }
-- and marker = { { level, x, y, icon, quest ID }, ... } (where a quest's
-- item, kill, vendor or escort is; boss = a pin's key draws it on that
-- boss's pin instead of at x, y; on = true draws it on the corner of the
-- marker at the same spot; area = { x1, y1, ... } outlines where it
-- applies, lit while the marker is hovered).
function ns.Data:RegisterMapSpots(spots)
    for id, s in pairs(spots) do
        local map = self.maps[id]
        if map then
            map.entrances = s.entrance
            map.locks = s.lock
            map.markers = s.marker
            for i, list in pairs(s.links or {}) do
                if map[i] then map[i].links = list end
            end
        end
    end
end

-- Boss portraits for the loot pane header (Data/Bosses.lua): per instance,
-- per encounter, { { name, creature display ID, level (-1 for ??), rank, NPC ID }, ... }.
function ns.Data:RegisterBosses(bosses)
