-- Damage and healing a boss's abilities were seen doing in combat logs
-- (end of Data/Abilities.lua and ForeverAbilities.lua): boss NPC ID =
-- { [spell ID] = { hit / tick / heal = { min, max, samples } } }.
function ns.Data:RegisterObserved(observed)
    for npc, spells in pairs(observed) do self.observed[npc] = spells end
end

