function ns.Data:Observed(npc, spellID)
    return npc and self.observed[npc] and self.observed[npc][spellID]
end

-- The encounter's bosses as { name, display, level, rank, npc } lists, or nil
-- when it has none to show (trash, loot pools, the new Forever bosses
-- before their model is known). The bosses new in Forever come from their
-- own data file's display and level and count as elite.
function ns.Data:Bosses(instance, encounter)
    local list = self.bosses[instance.id] and self.bosses[instance.id][encounter.id]
    if list then return list end
    if encounter.display then
        local level = encounter.level
        return { { encounter.name, encounter.display, level, level == -1 and "worldboss" or "elite", encounter.npc } }
    end
end

-- Who drops `entry` of `encounter`: the Ring of Law fighter it belongs to
-- (entry.boss, an index into the encounter's bosses), else the encounter.
function ns.Data:DropperName(instance, encounter, entry)
    if entry.boss then
        local bosses = self:Bosses(instance, encounter)
        local boss = bosses and bosses[entry.boss]
        if boss then return boss[1] end
    end
    return encounter.name
end

