-- The fold class `classToken`'s quest `questID` is listed under (see
-- RegisterClassQuestFolds), whether it is one of the quests that end its
-- stage, that stage (the fold, or its followUp) and, for a version step's
-- quest, the group its versions share; nil when none.
function ns.Data:ClassQuestFold(classToken, questID)
    local place = (self.classQuestFolds[classToken] or {})[questID]
    if not place then return nil end
    return place.fold, place.isEnd, place.stage, place.versionGroup
end

-- The trainer spells of the class with token `classToken`, or nil: the
-- shipped list, with the levels and costs the player has read at WoW:
-- Forever's class trainers since in place of the shipped ones (Core/Trainers.lua).
function ns.Data:ClassSpells(classToken)
    local shipped = self.classSpells[classToken]
    return shipped and ns.Trainers.Live(classToken, shipped)
end

-- The trainer spells of class `classToken` as Data/ClassSpells.lua ships them, or nil.
function ns.Data:ShippedClassSpells(classToken)
    return self.classSpells[classToken]
end

-- A class's own recipes, shaped as a profession's list (Data/Poisons.lua, the
-- rogue's poisons): { key, skillLine, recipes = { { spellID, itemID, skill,
-- level, cost or fromQuest, reagents }, ... }, quests = { { id, side,
-- giverNpc, giver }, ... } } becomes an instance like a profession's, with
-- `classToken` and `skillLine`, so its recipe page, skill colours and the
-- Shopping List treat it as one. Its category, CLASS, is no tab's: only the
-- Classes tab lists it. The recipes' names come from the game later
-- (UI/Poisons.lua).
-- Classic-DB has the skill each recipe is learned at, not where it turns
-- yellow, green and grey; these steps above it are a guess to check in game.
local CLASS_RECIPE_SKILL_STEPS = { 15, 30, 45 }
-- Each list's name, by its key: the Shopping List's "Made with Poisons".
local CLASS_RECIPE_NAMES = { POISONS = L["Poisons"] }

local function ClassRecipe(recipe, quests)
    local learnedAt = recipe.skill
    local skill = { learnedAt }
    for _, step in ipairs(CLASS_RECIPE_SKILL_STEPS) do table.insert(skill, learnedAt + step) end
    return { id = "S" .. recipe.spellID, name = "", spellID = recipe.spellID, skill = skill, level = recipe.level,
        cost = recipe.cost, quests = recipe.fromQuest and quests or nil, loot = { { itemID = recipe.itemID } },
        reagents = recipe.reagents }
end

function ns.Data:RegisterClassRecipes(classToken, data)
    local instance = { id = data.key, name = CLASS_RECIPE_NAMES[data.key] or data.key, category = "CLASS",
        classToken = classToken, skillLine = data.skillLine, quests = data.quests, encounters = {} }
    for _, recipe in ipairs(data.recipes) do table.insert(instance.encounters, ClassRecipe(recipe, data.quests)) end
    self:Register(instance)
    self.classRecipes[classToken] = instance
end

-- The class's own recipe list (an instance, see RegisterClassRecipes), or nil.
function ns.Data:ClassRecipes(classToken)
    return self.classRecipes[classToken]
end

-- The quest in `quests` with ID `questID` (a merged quest by any it covers).
local function QuestByID(quests, questID)
    if not questID then return nil end
    for _, quest in ipairs(quests) do
        if quest.id == questID then return quest end
        for _, id in ipairs(quest.alt or {}) do
            if id == questID then return quest end
        end
    end
end

-- One of the dungeon's quests by its ID (a merged quest by any it covers).
function ns.Data:DungeonQuest(instanceID, questID)
    return QuestByID(self:Quests(instanceID), questID)
end

-- One of a class's quests by its ID (one listed with others by any it covers).
function ns.Data:ClassQuest(classToken, questID)
    return QuestByID(self:ClassQuests(classToken), questID)
end

-- Which dungeons (and raids) each quest belongs to, one index per side,
-- built the first time a side is asked: the quest and chain lists never
-- change once loaded. side -> quest ID -> { { instance = ..., quest = the
-- instance's own quest it is, or a chain step of }, ... }.
local dungeonsOfQuest = {}

-- `instance` (with its quest `quest`) onto quest `questID`'s list in
-- `index`, once per instance: the first quest found for it stays.
local function AddDungeon(index, questID, instance, quest)
    local list = index[questID] or {}
    index[questID] = list
    for _, entry in ipairs(list) do
        if entry.instance == instance then return end
    end
    list[#list + 1] = { instance = instance, quest = quest }
end

-- Every quest ID on the chains through dungeon quest `quest` (under any of
-- its versions' IDs) that `side` can take, all their steps; without chain
-- data, the earlier steps the quest itself lists (its chain and chainStart).
local function ChainQuestIDs(data, quest, side)
    local ids = {}
    for _, versionID in ipairs({ quest.id, unpack(quest.alt or {}) }) do
        for _, chainIndex in ipairs(data:ChainsWith(versionID, side)) do
            for _, step in ipairs(data:FittingChain(chainIndex, side)) do
                for _, id in ipairs(step) do ids[#ids + 1] = id end
            end
        end
    end
    if #ids > 0 then return ids end
    -- A quest whose earlier steps differ by side keeps each side's under bySide.
    local sideFields = quest.bySide and quest.bySide[side] or quest
    for _, id in ipairs(sideFields.chain or {}) do ids[#ids + 1] = id end
    if sideFields.chainStart then ids[#ids + 1] = sideFields.chainStart end
    return ids
end

-- Whether `side` can take dungeon quest `quest`.
local function IsForSide(quest, side)
    return quest.side == nil or quest.side == side
end

local function BuildDungeonsOfQuest(data, side)
    local index, places = {}, {}
    for _, category in ipairs({ "DUNGEON", "RAID" }) do
        for _, instance in ipairs(data:List(category)) do places[#places + 1] = instance end
    end
    -- Each instance's own quests first, so a quest lists the instance it is
    -- a quest of ahead of the ones whose chains it only leads into.
    for _, instance in ipairs(places) do
        for _, quest in ipairs(data:Quests(instance.id)) do
            if IsForSide(quest, side) then
                AddDungeon(index, quest.id, instance, quest)
                for _, id in ipairs(quest.alt or {}) do AddDungeon(index, id, instance, quest) end
            end
        end
    end
    for _, instance in ipairs(places) do
        for _, quest in ipairs(data:Quests(instance.id)) do
            if IsForSide(quest, side) then
                for _, id in ipairs(ChainQuestIDs(data, quest, side)) do AddDungeon(index, id, instance, quest) end
            end
        end
    end
    return index
end

-- The dungeons and raids quest `questID` is part of for `side` ("Alliance"
-- or "Horde"), as { instance = ..., quest = ... } in list order: those it
-- is one of the quests of first (quest is that quest), then those whose
-- quest chains it is a step of (quest is the instance's quest on that
-- chain). Every tab, whether it is on or not. Empty when none.
function ns.Data:DungeonsOfQuest(questID, side)
    dungeonsOfQuest[side] = dungeonsOfQuest[side] or BuildDungeonsOfQuest(self, side)
    return dungeonsOfQuest[side][questID] or {}
end

-- Whether an encounter is a boss (rares included): not the Overview page,
-- trash or a shared loot pool.
function ns.Data:IsBoss(encounter)
    return not NOT_BOSSES[encounter.id]
end

-- How many bosses an instance has.
function ns.Data:BossCount(instance)
    local n = 0
    for _, encounter in ipairs(instance.encounters) do
        if self:IsBoss(encounter) then n = n + 1 end
    end
    return n
end

-- A list's name, with its side for a list only one side can use: "Alterac Valley (Horde)".
-- Empty for no list (an ID the data doesn't have).
function ns.Data:PlaceName(instance)
    if not instance then return "" end
    return instance.faction and ("%s (%s)"):format(instance.name, ns.SideName(instance.faction)) or instance.name
end

function ns.Data:Get(id)
    return self.instances[id]
end

function ns.Data:List(category)
    return self.byCategory[category] or {}
end

-- The recipe that makes `itemID`, as (profession, recipe encounter), or nil.
-- When several do, the one needing the least skill.
function ns.Data:RecipeFor(itemID)
    if not self.crafted then
        self.crafted = {}
        for _, instance in ipairs(self:List("PROFESSION")) do
            for _, encounter in ipairs(instance.encounters) do
                local made = encounter.spellID and encounter.loot[1]
                if made and not made.recipe then
                    local have = self.crafted[made.itemID]
                    if not have or (encounter.skill and have[2].skill and encounter.skill[1] < have[2].skill[1]) then
                        self.crafted[made.itemID] = { instance, encounter }
                    end
                end
            end
        end
    end
    local found = self.crafted[itemID]
    if found then return found[1], found[2] end
end

-- Instances shown as one, their parts as fold-out wings under Encounters:
-- Stratholme's Live and Undead halves. The data files keep each part as its
-- own instance; once every file has loaded the parts are joined into one
-- instance in their place (the first part's spot in the list), and the
-- parts' IDs keep finding it. Its encounters carry `wing` = the part's name.
local MERGED = {
    { id = "STRATHOLME", name = "Stratholme", parts = { { "STRAT_LIVE", "Live" }, { "STRAT_UNDEAD", "Undead" } } },
}

function ns.Data:MergeWings()
    for _, def in ipairs(MERGED) do
        local parts = {}
        for _, p in ipairs(def.parts) do
            local instance = self.instances[p[1]]
            if instance then table.insert(parts, { inst = instance, wing = p[2] }) end
        end
        if #parts == #def.parts then
            local first = parts[1].inst
            local merged = { id = def.id, name = def.name, category = first.category, zone = first.zone,
                             encounters = {}, wings = {} }
            local lore, quests, seen = {}, {}, {}
            local low, high
            for _, part in ipairs(parts) do
                local instance = part.inst
                table.insert(merged.wings, part.wing)
                for _, encounter in ipairs(instance.encounters) do
                    if not encounter.overview then
                        encounter.wing = part.wing
                        table.insert(merged.encounters, encounter)
                    end
                end
                local range = instance.levelRange
                if range then
                    low = math.min(low or range[1], range[1])
                    high = math.max(high or range[2], range[2])
                end
                table.insert(lore, self.lore and self.lore[instance.id])
                for _, q in ipairs(self:Quests(instance.id)) do
                    if not seen[q.id] then seen[q.id] = true; table.insert(quests, q) end
                end
            end
            merged.levelRange = low and { low, high }
            table.insert(merged.encounters, 1, { id = "OVERVIEW", name = L["Overview"], overview = true, loot = {} })

            -- In the list, the joined instance takes the first part's place.
            local list = self.byCategory[first.category]
            for i = #list, 1, -1 do
                local instance = list[i]
                if instance == first then
                    list[i] = merged
                else
                    for _, part in ipairs(parts) do
                        if instance == part.inst then table.remove(list, i) end
                    end
                end
            end
            self.instances[def.id] = merged
            for _, part in ipairs(parts) do self.instances[part.inst.id] = merged end

            self.quests[def.id] = quests
            -- Boss portraits stay keyed by encounter, so the parts' lists join.
            local bosses = {}
            for _, part in ipairs(parts) do
                for encounterID, list in pairs(self.bosses[part.inst.id] or {}) do bosses[encounterID] = list end
            end
            self.bosses[def.id] = bosses
            if self.lore and #lore > 0 then self.lore[def.id] = table.concat(lore, "\n\n") end
            self.entrances[def.id] = self.entrances[first.id]
            -- One layout map: the first part's levels with every part's boss
            -- pins and entrances.
            local base = self.maps[first.id]
            if base then
                local map = { credit = base.credit, entrances = {} }
                for _, part in ipairs(parts) do
                    local m = self.maps[part.inst.id]
                    for _, spot in ipairs(m and m.entrances or {}) do table.insert(map.entrances, spot) end
                    for _, spot in ipairs(m and m.markers or {}) do
                        map.markers = map.markers or {}
                        table.insert(map.markers, spot)
                    end
                end
                for i, level in ipairs(base) do
                    local copy = {}
                    for k, v in pairs(level) do copy[k] = v end
                    local pins = {}
                    for _, part in ipairs(parts) do
                        local m = self.maps[part.inst.id]
                        for _, pin in ipairs(m and m[i] and m[i].pins or {}) do table.insert(pins, pin) end
                    end
                    copy.pins = #pins > 0 and pins or nil
                    map[i] = copy
                end
                self.maps[def.id] = map
            end
        end
    end
end

-- WoW: Forever's look-alike recipes, found while the names are still
-- English (Core/Names.lua renames them later on other clients). Many new
-- pieces come in variants: colours (Flame/Pearly/... Boots, Azure/Cloudy
-- Skyforged Chain) or roles (Acolyte's/Crusader's/... Gloves). A series is
-- every piece made in the same variants; its recipes share
-- encounter.series (the series' recipes in data order, with series.words,
-- its variant words in order) and each has encounter.tint, its own variant
-- word. The recipe list (UI/RecipeBand.lua) folds a series into one row
-- with its variant picked on top.
local COLOUR_WORDS = {}
for word in ([[Flame Pearly Pristine Shadow Shining Silky Black Fiery Frothing Gilded Golden Radiant
    Netherflame Netherfroth Nethergeld Netherlight Netherpearl Nethershine Azure Cloudy]]):gmatch("%S+") do
    COLOUR_WORDS[word] = true
end
-- The role series, each in the order its variants are offered.
local ROLE_SERIES = {
    -- Blacksmithing
    { "Acolyte's", "Crusader's", "Guard's", "Protector's", "Veteran's" },
    { "Justicar's", "Officer's", "Prefect's", "Sentinel's", "Warder's" },
    { "Clutchlord's", "Goregasher" },
    -- Leatherworking
    { "Brawler's", "Defender's", "Stormrider's", "Totemic", "Trapper's", "Wisdom's" },
    { "Mender's", "Prowler's", "Skirmisher's", "Skulker's", "Skycaller's", "Stalker's", "Warden's" },
    { "Bileblister", "Broodwatcher's", "Hivethrasher's", "Scalegut" },
    -- Tailoring
    { "Swarmtender's", "Venomspew" },
}
local ROLE_SERIES_OF = {}
for _, words in ipairs(ROLE_SERIES) do
    for _, word in ipairs(words) do ROLE_SERIES_OF[word] = words end
end
-- A name's colour word and the name without it ("Boots" for Flame Boots,
-- "Filigreed Gown" for Filigreed Flame Gown), or nil.
local function ColourOf(name)
    local lead, word, rest = name:match("^(Filigreed )(%S+) (.+)$")
    if not (word and COLOUR_WORDS[word]) then
        lead, word, rest = "", name:match("^(%S+) (.+)$")
    end
    if word and COLOUR_WORDS[word] then return word, lead .. rest end
end
-- Forever's named gear sets with no variants, which span slots and skills
-- (Grovekeeper ..., Hard Gold ...): their recipes share encounter.family (the
-- set's recipes, in data order) and encounter.familyName, and the list folds
-- each into one row too. By the words a recipe's name starts with, past a
-- colour word: a family made in colours (Skyforged) is also a series.
local FAMILIES = {}
for _, name in ipairs({
    -- Tailoring
    "Stormsewn", "Earthenweave", "Ghostweave", "Demonheart", "Manaflare",
    -- Leatherworking
    "Gustwoven", "Windraveled", "Grovekeeper", "Spiritcaller", "Charged Scorpid", "Supple Scorpid",
    "Tooled Leather", "Blue Suede", "Grimstitch", "Wildstalker's",
    -- Blacksmithing
    "Skyforged", "Justice", "Blessed Plate", "Hard Gold", "Sterling Silver",
}) do
    FAMILIES[name] = name
end
-- Earthen Silk ... with Earthen Leggings and Earthen Vest: one set.
FAMILIES["Earthen Silk"], FAMILIES["Earthen Leggings"], FAMILIES["Earthen Vest"] = "Earthen", "Earthen", "Earthen"
local function FamilyOf(name)
    local _, rest = ColourOf(name)
    rest = rest or name
    local one, two = rest:match("^(%S+)"), rest:match("^(%S+ %S+)")
    return two and FAMILIES[two] or one and FAMILIES[one]
end

-- `members` as a set shared by each of them under `field`, if there are 2 or more.
local function Share(groups, field)
    for _, members in pairs(groups) do
        if #members >= 2 then
            for _, encounter in ipairs(members) do encounter[field] = members end
        end
    end
end

-- The colour series in `instance`: each piece (its name without the colour
-- word, at one skill) made in 2 or more colours joins the series of its
-- gear set, or else of the pieces made in the same colours.
local function ColourSeries(instance)
    local pieces, pieceOrder = {}, {}
    for _, encounter in ipairs(instance.encounters) do
        local word, base = ColourOf(encounter.name or "")
        if encounter.note == "new" and word and encounter.skill then
            local key = base .. "|" .. table.concat(encounter.skill, ",")
            if not pieces[key] then
                pieces[key] = {}
                table.insert(pieceOrder, key)
            end
            table.insert(pieces[key], encounter)
        end
    end
    local series = {}
    for _, key in ipairs(pieceOrder) do
        local piece = pieces[key]
        if #piece >= 2 then
            local words = {}
            for i, encounter in ipairs(piece) do words[i] = (ColourOf(encounter.name)) end
            local lead = piece[1].name:match("^Filigreed ") or ""
            table.sort(words)
            local seriesKey = piece[1].familyName or (lead .. table.concat(words, " "))
            series[seriesKey] = series[seriesKey] or {}
            for _, encounter in ipairs(piece) do
                encounter.tint = (ColourOf(encounter.name))
                table.insert(series[seriesKey], encounter)
            end
        end
    end
    return series
end

-- The role series in `instance`, by the role word a recipe's name starts with.
local function RoleSeries(instance)
    local series = {}
    for _, encounter in ipairs(instance.encounters) do
        local word = (encounter.name or ""):match("^(%S+) ")
        local roles = encounter.note == "new" and ROLE_SERIES_OF[word]
        if roles then
            series[roles] = series[roles] or {}
            table.insert(series[roles], encounter)
            encounter.tint = word
        end
    end
    return series
end

-- A series' variant words, in the order its recipes first use them (a
-- role series: its list's order).
local function SeriesWords(members, roles)
    if roles then return roles end
    local words, seen = {}, {}
    for _, encounter in ipairs(members) do
        if not seen[encounter.tint] then
            seen[encounter.tint] = true
            table.insert(words, encounter.tint)
        end
    end
    return words
end

function ns.Data:GroupColourSets()
    for _, instance in ipairs(self:List("PROFESSION")) do
        local families = {}
        for _, encounter in ipairs(instance.encounters) do
            local family = encounter.note == "new" and FamilyOf(encounter.name or "")
            if family then
                families[family] = families[family] or {}
                table.insert(families[family], encounter)
            end
        end
        for name, members in pairs(families) do
            if #members >= 2 then
                for _, encounter in ipairs(members) do encounter.family, encounter.familyName = members, name end
            end
        end
        local roleSeries, colourSeries = RoleSeries(instance), ColourSeries(instance)
        for roles, members in pairs(roleSeries) do members.words = SeriesWords(members, roles) end
        for _, members in pairs(colourSeries) do members.words = SeriesWords(members) end
        Share(roleSeries, "series")
        Share(colourSeries, "series")
    end
end

ns:On("ADDON_LOADED", function(loaded)
    if loaded == ns.name then
        ns.Data:MergeWings()
        ns.Data:GroupColourSets()
    end
end)
